const s=$input.first().json;
for(const k of ['campaign','source','medium'])if(typeof s[k]!=='string'||!s[k].trim()||s[k].length>150)throw Error(k+' must have 1–150 characters');
if(!Array.isArray(s.placements)||!s.placements.length||s.placements.length>50)throw Error('Provide 1–50 placements');
if(!Array.isArray(s.approvedHosts)||!s.approvedHosts.length)throw Error('Set approvedHosts to public domains you control');
if(!Number.isInteger(s.maxBodyCharacters)||s.maxBodyCharacters<1000||s.maxBodyCharacters>1000000)throw Error('maxBodyCharacters must be 1000–1000000');
if(typeof s.sendEmail!=='boolean')throw Error('sendEmail must be true or false');
if(s.sendEmail&&(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(s.fromEmail)||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(s.toEmail)))throw Error('Set sender and recipient before enabling email');
const hosts=new Set(s.approvedHosts.map(x=>String(x).trim().toLowerCase()));const groups=new Map();
for(const [i,p]of s.placements.entries()){
 if(!p||typeof p.url!=='string'||p.url.length>4000||/[\s\\\u0000-\u001f]/.test(p.url))throw Error('Invalid URL at row '+(i+1));
 const m=/^https:\/\/([a-z0-9.-]+)(\/[^?#]*)?(\?[^#]*)?(#.*)?$/i.exec(p.url);
 if(!m)throw Error('Use HTTPS URLs without ports, credentials or IP literals at row '+(i+1));
 const host=m[1].toLowerCase();if(!/^[a-z0-9](?:[a-z0-9.-]*[a-z0-9])?\.[a-z]{2,63}$/.test(host)||host.split('.').some(x=>!x||x.startsWith('-')||x.endsWith('-'))||/(^|\.)(localhost|local|internal|test|invalid|onion|home|lan)$/.test(host)||!hosts.has(host))throw Error('Unapproved public hostname at row '+(i+1));
 const base='https://'+host+(m[2]||'/');const parts=(m[3]||'').slice(1).split('&').filter(Boolean).filter(v=>{try{return !decodeURIComponent(v.split('=')[0].replace(/\+/g,' ')).toLowerCase().startsWith('utm_');}catch{throw Error('Malformed URL encoding at row '+(i+1));}});
 const destination=base+(parts.length?'?'+parts.join('&'):'');const utm={source:s.source,medium:s.medium,campaign:s.campaign,content:p.content||String(i+1)};
 const tracking=destination+(parts.length?'&':'?')+Object.entries(utm).map(([k,v])=>'utm_'+k+'='+encodeURIComponent(String(v).trim())).join('&')+(m[4]||'');
 const placement={row:i+1,label:String(p.label||'Placement '+(i+1)),trackingUrl:tracking,expectedText:String(p.expectedText||'').slice(0,500)};
 if(!groups.has(destination))groups.set(destination,{destination,placements:[],maxBodyCharacters:s.maxBodyCharacters});groups.get(destination).placements.push(placement);
}
return [...groups.values()].map(json=>({json}));

return $input.all().flatMap((item,i)=>{
 const plan=$('Validate manifest and build tracking links').itemMatching(i).json,r=item.json;
 const status=Number(r.statusCode||0),h=Object.fromEntries(Object.entries(r.headers||{}).map(([k,v])=>[k.toLowerCase(),String(v)]));const raw=typeof r.body==='string'?r.body:typeof r.data==='string'?r.data:'';
 const oversized=raw.length>plan.maxBodyCharacters,body=raw.slice(0,plan.maxBodyCharacters);const title=(/<title\b[^>]*>([\s\S]*?)<\/title>/i.exec(body)||[])[1]?.replace(/\s+/g,' ').trim()||'';
 const tags=body.match(/<(?:meta|link)\b[^>]*>/gi)||[];const attr=(tag,name)=>{const m=new RegExp('\\b'+name+'\\s*=\\s*["\x27]([^"\x27]*)["\x27]','i').exec(tag);return m?m[1]:'';};
 const noindex=/noindex/i.test(h['x-robots-tag']||'')||tags.some(t=>/^(robots|googlebot)$/i.test(attr(t,'name'))&&/noindex/i.test(attr(t,'content')));
 const canonical=tags.filter(t=>attr(t,'rel').toLowerCase().split(/\s+/).includes('canonical')).map(t=>attr(t,'href')).filter(Boolean).join(' | ');
 return plan.placements.map(p=>{const issues=[];let priority='PASS';const add=(level,message)=>{if(level==='BLOCKER'||priority==='PASS')priority=level;issues.push(message);};
 if(!status)add('BLOCKER','Request failed or timed out');else if(status>=300&&status<400)add('BLOCKER','Redirect: use the verified final destination');else if(status<200||status>=400)add('BLOCKER','HTTP '+status);
 if(status>=200&&status<300){if(!/text\/html|application\/xhtml\+xml/i.test(h['content-type']||''))add('REVIEW','Response is not declared HTML');if(!title)add('REVIEW','Title not found in returned HTML');if(noindex)add('REVIEW','Noindex directive: confirm this is intentional');if(p.expectedText&&!body.toLowerCase().includes(p.expectedText.toLowerCase()))add('REVIEW','Expected text absent from returned HTML');if(oversized)add('REVIEW','Body analysis truncated at configured character limit');}
 return {json:{...p,destination:plan.destination,httpStatus:status,priority,issues:issues.join('; '),title:title.slice(0,300),canonical:canonical.slice(0,1000),redirectLocation:(h.location||'').slice(0,1000),nextAction:priority==='BLOCKER'?'Fix destination before launch':priority==='REVIEW'?'Review page evidence':'Ready for manual launch review'}};
 });
});

const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const safe=v=>typeof v==='string'&&/^[=+@\-\t\r]/.test(v)?"'"+v:v;
const rows=$input.all().map(x=>x.json).sort((a,b)=>({BLOCKER:0,REVIEW:1,PASS:2}[a.priority]-{BLOCKER:0,REVIEW:1,PASS:2}[b.priority])||a.row-b.row);const s=$('Campaign audit settings').first().json;
const counts=rows.reduce((a,r)=>(a[r.priority]++,a),{BLOCKER:0,REVIEW:0,PASS:0});const uniqueRequests=new Set(rows.map(r=>r.destination)).size;
const html='<!doctype html><meta charset="utf-8"><title>Campaign launch audit</title><h1>'+esc(s.campaign)+'</h1><p>'+rows.length+' placements, '+uniqueRequests+' unique destinations. '+counts.BLOCKER+' blockers; '+counts.REVIEW+' review items.</p><table border="1" cellpadding="8"><tr><th>Placement</th><th>Priority</th><th>Status</th><th>Findings</th><th>Next action</th></tr>'+rows.map(r=>'<tr><td>'+esc(r.label)+'</td><td>'+r.priority+'</td><td>'+r.httpStatus+'</td><td>'+esc(r.issues||'No configured checks failed')+'</td><td>'+esc(r.nextAction)+'</td></tr>').join('')+'</table><p>Snapshot only. Not a browser, conversion or security audit. Redirect targets were not fetched.</p>';
return [{json:{campaign:s.campaign,rows,counts,uniqueRequests,html,sendEmail:s.sendEmail,fromEmail:s.fromEmail,toEmail:s.toEmail,subject:'Launch audit: '+s.campaign+' — '+counts.BLOCKER+' blockers'}}];
